// Journal aggregates for `context-gate report` and `/gate why` (SPEC "Ескалація", сценарії 8 і 11,
// "Промпти як skills"). Pure, over `.claude/gate.log.jsonl` entries; no Node.

import type { DecisionLogEntry, GateConfig, Item } from './types.ts'
import { enablingGroup } from './decide.ts'

// ───────────────────────── attempts and tokens per tier per task (G-09) ─────────────────────────

export interface TierCost { tier: string; attempts: number; failed: number; passed: number; turns: number; tokens: number }
export interface TaskCost { task: string; tiers: TierCost[] }

const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0)

/** Tokens an entry carries: `data.tokens`, or `data.usage` (`input_tokens` + cache tokens + `output_tokens`). */
export function entryTokens(e: DecisionLogEntry): number {
  const d = e.data ?? {}
  if (typeof d.tokens === 'number') return num(d.tokens)
  const u = d.usage as Record<string, unknown> | undefined
  if (!u || typeof u !== 'object') return 0
  return num(u.input_tokens) + num(u.cache_read_input_tokens) + num(u.cache_creation_input_tokens) + num(u.output_tokens)
}

/** A verification attempt: a Verify run (runner), a command gate, or a failed test/lint Bash call (mod).
 * A command gate is counted from its `gate-attempt` entries (`pass` and `block`); its `gate-failed` twin is
 * then skipped (`attemptGates`: gates that have `gate-attempt` entries), so a block counts once. */
function attemptOf(e: DecisionLogEntry, attemptGates: ReadonlySet<string>): 'passed' | 'failed' | undefined {
  if ((e.kind as string) === 'gate-attempt') {
    const o = e.data?.outcome
    return o === 'pass' ? 'passed' : o === 'block' ? 'failed' : undefined
  }
  if (e.kind === 'gate-failed') return attemptGates.has(gateName(e)) ? undefined : 'failed'
  if (e.trigger === 'verify' && e.data?.gate === 'verify') return e.data?.passed === true ? 'passed' : 'failed'
  if (e.kind === 'debug' && e.trigger === 'verify-failed') return 'failed'
  return undefined
}

/**
 * How many attempts and tokens each tier cost on each task. The task is `data.ticket` (shiftwork) or
 * `data.ticketId`, else `сесія`; the tier is the entry's own. Tokens come only from entries that carry them.
 */
export function tierCosts(entries: readonly DecisionLogEntry[]): TaskCost[] {
  const tasks = new Map<string, Map<string, TierCost & { turnSet: Set<number> }>>()
  const attemptGates = new Set(entries.filter((e) => (e.kind as string) === 'gate-attempt').map(gateName))
  for (const e of entries) {
    const tier = e.tier || '?'
    const task = String(e.data?.ticket ?? e.data?.ticketId ?? 'сесія')
    const att = attemptOf(e, attemptGates)
    const tokens = entryTokens(e)
    if (!att && !tokens && e.kind !== 'decision') continue
    const byTier = tasks.get(task) ?? new Map()
    tasks.set(task, byTier)
    const c = byTier.get(tier) ?? { tier, attempts: 0, failed: 0, passed: 0, turns: 0, tokens: 0, turnSet: new Set<number>() }
    byTier.set(tier, c)
    if (att) { c.attempts++; c[att]++ }
    c.tokens += tokens
    if (typeof e.turn === 'number') c.turnSet.add(e.turn)
  }
  const out: TaskCost[] = []
  for (const [task, byTier] of tasks) {
    const tiers = [...byTier.values()].filter((c) => c.attempts || c.tokens).map(({ turnSet, ...c }) => ({ ...c, turns: turnSet.size }))
    if (tiers.length) out.push({ task, tiers })
  }
  return out
}

/** The gate an entry belongs to: `data.gate`, else the trigger (`read-before-write`). */
function gateName(e: DecisionLogEntry): string {
  return typeof e.data?.gate === 'string' ? e.data.gate : String(e.trigger)
}

/** `| задача | tier | спроб | невдалих | токенів |` for `/gate why` and `report`. */
export function formatTierCosts(costs: readonly TaskCost[]): string {
  if (!costs.length) return 'Спроб перевірки за tier ще не було.'
  const rows = ['| задача | tier | спроб | невдалих | пройдено | токенів |', '| --- | --- | --- | --- | --- | --- |']
  for (const t of costs) for (const c of t.tiers) rows.push(`| ${t.task} | ${c.tier} | ${c.attempts} | ${c.failed} | ${c.passed} | ${c.tokens || '—'} |`)
  return rows.join('\n')
}

// ───────────────────────── deny suggestions (сценарій 8, G-55) ─────────────────────────

export interface DenySuggestion { profile: string; kind: Item['kind']; name: string; count: number; group?: string; text: string }

/** `mcp__postgres__query` / `tool:mcp__postgres__query` / `skill:x` (the mod's `data.skill`) → kind + name.
 * Shared by `report` and the pipeline's `observe` counts. */
export function deniedItem(e: DecisionLogEntry): { kind: Item['kind']; name: string } | undefined {
  const d = e.data ?? {}
  const raw = typeof d.tool === 'string' ? d.tool : typeof d.skill === 'string' ? `skill:${d.skill}` : typeof d.id === 'string' ? d.id : typeof d.name === 'string' ? d.name : undefined
  if (!raw) return undefined
  const m = /^(skill|tool|agent|rule):(.+)$/.exec(raw)
  if (m) return { kind: m[1] as Item['kind'], name: m[2]! }
  return { kind: typeof d.skill === 'string' ? 'skill' : 'tool', name: raw }
}

/**
 * Repeated denies of one item under one profile → «додай групу в профіль». The profile is the entry's own,
 * else that of the latest `decision` before it. `min` is the H010 threshold (more than 3 by default).
 */
export function denySuggestions(entries: readonly DecisionLogEntry[], config: GateConfig | undefined, min = 3): DenySuggestion[] {
  const counts = new Map<string, { profile: string; kind: Item['kind']; name: string; count: number }>()
  let profile: string | undefined
  for (const e of entries) {
    // Every decision resets the running profile: after one with no profile (tier only, `/gate auto`), later
    // denies belong to no profile and are not attributed to a stale one.
    if (!e.kind || e.kind === 'decision') { if (e.trigger !== 'verify') profile = e.profile; continue }
    if (e.kind !== 'deny' || e.trigger === 'strictWrite' || e.data?.shadow === true) continue
    const it = deniedItem(e)
    const p = e.profile ?? profile
    if (!it || !p) continue
    const key = `${p}\0${it.kind}\0${it.name}`
    const c = counts.get(key) ?? { profile: p, ...it, count: 0 }
    c.count++
    counts.set(key, c)
  }
  const out: DenySuggestion[] = []
  for (const c of counts.values()) {
    if (c.count <= min) continue
    const group = config ? enablingGroup(c.kind, c.name, config) : undefined
    const label = c.kind === 'tool' && c.name.startsWith('mcp__') ? c.name.split('__')[1] ?? c.name : c.name
    const text = group
      ? `${label}: ${c.count} deny у профілі ${c.profile} → додай групу \`${group}\` у \`profiles.${c.profile}.groups\` (на сесію: /gate +${group})`
      : `${label}: ${c.count} deny у профілі ${c.profile} → додай його в групу профілю ${c.profile}`
    out.push({ ...c, ...(group ? { group } : {}), text })
  }
  return out.sort((a, b) => b.count - a.count)
}

// ───────────────────────── runner vs mod by ticketId (сценарій 11, G-55) ─────────────────────────

export interface TicketComparison { ticket: string; ticketType?: string; runner?: string; mod?: string; agree: boolean }

const ticketOf = (e: DecisionLogEntry): string | undefined => {
  const t = e.data?.ticket ?? e.data?.ticketId
  return typeof t === 'string' && t ? t : undefined
}

/**
 * The runner's (`data.adapter: shiftwork`) and the mod's/hooks adapter's latest profile per ticket. A mod
 * decision belongs to a ticket by `data.ticket`/`data.ticketId`, else by the same `data.ticketType`.
 */
export function compareRunnerMod(entries: readonly DecisionLogEntry[]): TicketComparison[] {
  const runner = new Map<string, { profile?: string; ticketType?: string }>()
  const modByTicket = new Map<string, string | undefined>()
  const modByType = new Map<string, string | undefined>()
  for (const e of entries) {
    if (e.kind && e.kind !== 'decision') continue
    if (e.trigger === 'verify') continue
    const t = ticketOf(e)
    const type = typeof e.data?.ticketType === 'string' ? e.data.ticketType : undefined
    if (e.data?.adapter === 'shiftwork') {
      if (t) runner.set(t, { profile: e.profile, ...(type ? { ticketType: type } : {}) })
    } else {
      if (t) modByTicket.set(t, e.profile)
      if (type) modByType.set(type, e.profile)
    }
  }
  const out: TicketComparison[] = []
  for (const [ticket, r] of runner) {
    const has = modByTicket.has(ticket) || (r.ticketType !== undefined && modByType.has(r.ticketType))
    if (!has) continue
    const mod = modByTicket.has(ticket) ? modByTicket.get(ticket) : modByType.get(r.ticketType!)
    out.push({ ticket, ...(r.ticketType ? { ticketType: r.ticketType } : {}), ...(r.profile ? { runner: r.profile } : {}), ...(mod ? { mod } : {}), agree: (r.profile ?? '') === (mod ?? '') })
  }
  return out
}

// ───────────────────────── shadow agreement (MVP exit criterion, M2) ─────────────────────────

export interface ShadowAgreement {
  /** Decisions that carry a proposal (`data.proposed`, the shadow classifier/`when` result). */
  proposed: number
  /** Proposals with a reference: a `label` entry or a later manual choice (`/gate <p>`, `[gate:p]`) in that turn
   * window, or the profile a `classify` or `manual` decision itself committed. */
  labeled: number
  matched: number
  differed: number
  /** Proposals nobody confirmed or corrected: not counted in the agreement. */
  unlabeled: number
  /** matched / labeled, 0…1; undefined while nothing is labeled. */
  rate?: number
}

const partsOf = (p: unknown): string[] => (typeof p === 'string' && p ? p.split('+') : [])

/**
 * Agreement of shadow proposals with the profile the user actually wanted (SPEC: MVP exit ≥ 80 %). Shadow
 * decisions carry no `profile`, so the reference is, in order: a `label` entry after the proposal and before
 * the next proposal (`data.profile` the correct profile, or `data.correct: true|false`), a `manual` decision
 * in that window (the user overrode or confirmed it), else the decision's own `profile` when the classifier set it or
 * the user did (trigger `classify` / `manual`; a `when`/sticky profile is not a verdict on the proposal). A
 * proposal with no reference is `unlabeled`, never a mismatch.
 */
export function shadowAgreement(entries: readonly DecisionLogEntry[]): ShadowAgreement {
  const r: ShadowAgreement = { proposed: 0, labeled: 0, matched: 0, differed: 0, unlabeled: 0 }
  const isDecision = (e: DecisionLogEntry) => (!e.kind || e.kind === 'decision') && e.trigger !== 'verify'
  const proposalOf = (e: DecisionLogEntry): string | undefined => {
    const p = (e.data?.proposed as { profile?: unknown } | undefined)?.profile
    return isDecision(e) && typeof p === 'string' && p ? p : undefined
  }
  for (let i = 0; i < entries.length; i++) {
    const e = entries[i]!
    const proposal = proposalOf(e)
    if (!proposal) continue
    r.proposed++
    let verdict: boolean | undefined
    for (let j = i + 1; j < entries.length && verdict === undefined; j++) {
      const x = entries[j]!
      if (proposalOf(x)) break
      if ((x.kind as string) === 'label') {
        const d = x.data ?? {}
        if (typeof d.correct === 'boolean') verdict = d.correct
        else if (typeof d.profile === 'string') verdict = partsOf(d.profile).includes(proposal)
      } else if (isDecision(x) && x.trigger === 'manual' && x.profile) verdict = partsOf(x.profile).includes(proposal)
    }
    // The decision's own profile is a reference when the classifier applied it or the user chose it (`manual`); a
    // `when` or sticky profile next to a shadow proposal was not influenced by it and says nothing about it (M2).
    if (verdict === undefined && (e.trigger === 'classify' || e.trigger === 'manual') && e.profile && e.data?.shadow !== true) verdict = partsOf(e.profile).includes(proposal)
    if (verdict === undefined) { r.unlabeled++; continue }
    r.labeled++
    if (verdict) r.matched++
    else r.differed++
  }
  if (r.labeled) r.rate = r.matched / r.labeled
  return r
}

// ───────────────────────── skill-prompt renders (G-28) ─────────────────────────

export interface SkillRenderStat { skill: string; renders: number; avgMs: number; avgChars: number; failed: number; args: string[] }

/** `skill-render` entries per skill: count, mean ms and chars, non-ok renders, up to 3 distinct arg samples. */
export function skillRenderStats(entries: readonly DecisionLogEntry[], samples = 3): SkillRenderStat[] {
  const by = new Map<string, { renders: number; ms: number; chars: number; failed: number; args: Set<string> }>()
  for (const e of entries) {
    if (e.kind !== 'skill-render' || typeof e.data?.skill !== 'string') continue
    const s = by.get(e.data.skill) ?? { renders: 0, ms: 0, chars: 0, failed: 0, args: new Set<string>() }
    by.set(e.data.skill, s)
    s.renders++
    s.ms += num(e.data.ms)
    s.chars += num(e.data.chars)
    if (e.data.status !== undefined && e.data.status !== 'ok') s.failed++
    if (e.data.args !== undefined && s.args.size < samples) s.args.add(JSON.stringify(e.data.args).slice(0, 120))
  }
  return [...by].map(([skill, s]) => ({ skill, renders: s.renders, avgMs: Math.round(s.ms / s.renders), avgChars: Math.round(s.chars / s.renders), failed: s.failed, args: [...s.args] }))
}

// ───────────────────────── gate counters from the journal (H011 in the CLI) ─────────────────────────

/** Blocks per gate from `gate-failed`; overrides from `gate-attempt {outcome: override}` (the current contract,
 * core journal.ts). Legacy `debug {trigger: gate-override}` entries count only for gates with no `gate-attempt`
 * override, so a journal holding both forms never counts one «все одно» twice. */
export function gateFailures(entries: readonly DecisionLogEntry[]): Record<string, { blocks: number; overrides: number }> {
  const out: Record<string, { blocks: number; overrides: number }> = {}
  const legacy: Record<string, number> = {}
  const modern = new Set<string>()
  for (const e of entries) {
    const g = typeof e.data?.gate === 'string' ? e.data.gate : undefined
    if (!g) continue
    if (e.kind === 'gate-failed') (out[g] ??= { blocks: 0, overrides: 0 }).blocks++
    else if ((e.kind as string) === 'gate-attempt' && e.data?.outcome === 'override') { modern.add(g); (out[g] ??= { blocks: 0, overrides: 0 }).overrides++ }
    else if (e.kind === 'debug' && e.trigger === 'gate-override') legacy[g] = (legacy[g] ?? 0) + 1
  }
  for (const [g, n] of Object.entries(legacy)) if (!modern.has(g)) (out[g] ??= { blocks: 0, overrides: 0 }).overrides += n
  return out
}

files.hooks/layers/host.ts:
// RenderHost over $ (MOD-ADAPTER "RenderHost"): files via io.fs (inside the repo only), executors via
// io.process.run (trusted repo + binary whitelist + interactive or userConfig.allowScripts), MCP via
// io.mcp.call (trusted only), cache/data via io.store, lazy includes as registered tools.
// Repo text is data: code reaches executors only as the AST's own `run` code; inputs go through stdin.
// Executors, language shims (`@call`, module providers, G158 `__exports__`) and `scripts.*` are core `shims.ts`,
// the same argv `context-gate run` starts.

import type { ExecutorConfig, MdcRule, ProviderConfig, Value } from '../../packages/core/src/types.ts'
import type { ProviderCallRequest, RenderHostExt } from '../../packages/core/src/render.ts'
import { compileGlob, hasGlobChars } from '../../packages/core/src/glob.ts'
import { exampleValue, selectExamples } from '../../packages/core/src/examples.ts'
import { cursorMatch } from '../../packages/core/src/assemble.ts'
import { parseDuration } from '../../packages/core/src/duration.ts'
import { fileProviderValue, markdownProviderValue, pickFields, providerResultOk } from '../../packages/core/src/providers.ts'
import { binaryWhitelist } from '../../packages/core/src/config.ts'
import { DEFAULT_EXECUTORS as CORE_EXECUTORS, executorEnv, executorFor, executorInvocation, executorsOf, parseShimOutput, scriptArgv, scriptFnName, scriptLang, scriptStdin, shimCommand, type ShimCall, type ShimResponse } from '../../packages/core/src/shims.ts'
import { type Io, OWN_TOOL_PREFIX, type Runtime, debug, hash, insideRoot, join, now } from '../ctx.ts'

/** The executors `@run` knows without gate.json (core, same as the CLI). */
export const DEFAULT_EXECUTORS: Record<string, ExecutorConfig> = CORE_EXECUTORS

/** Provider names the scope owns; config entries under these names are not providers (CLI `BUILTIN_PROVIDERS`). */
export const BUILTIN_PROVIDERS = new Set(['git', 'fs', 'cursor', 'session', 'gate', 'ctx', 'scripts', 'data', 'args', 'budgets'])

/** User `~/.claude/context-gate.json` `allowBinaries` (or core DEFAULT_BINARIES), narrowed by gate.json `allowBinaries`: core `binaryWhitelist`, as the CLI. */
export async function loadWhitelist(io: Io, rt: Runtime): Promise<string[]> {
  if (rt.whitelist) return rt.whitelist
  let user: string[] | undefined
  try {
    const home = await io.env.home()
    if (home) {
      const t = await io.fs.read(`${home}/.claude/context-gate.json`).catch(() => undefined)
      if (typeof t === 'string') {
        const v = JSON.parse(t) as { allowBinaries?: unknown }
        if (Array.isArray(v.allowBinaries)) user = v.allowBinaries.filter((x): x is string => typeof x === 'string')
      }
    }
  } catch (err) {
    debug(io, `whitelist read failed: ${String(err)}`)
  }
  rt.whitelist = binaryWhitelist(user, rt.cfg?.allowBinaries)
  return rt.whitelist
}

const binOf = (argv: readonly string[]): string => (argv[0] ?? '').split(/[\\/]/).pop() ?? ''

/** S5: the whitelist names binaries the user's PATH resolves. A path in `argv[0]` (`./tools/node`, `/tmp/x/git`) would
 *  pass a basename check while starting any file, so only a bare command name may start. */
export function bareBinary(argv: readonly string[]): boolean {
  const a = argv[0] ?? ''
  return a !== '' && !/[\\/]/.test(a)
}

/** May repo config start this argv? (trust is checked by the caller). */
export async function allowedBinary(io: Io, rt: Runtime, argv: readonly string[]): Promise<boolean> {
  if (!rt.interactive && !rt.options.allowScripts) return false
  if (!bareBinary(argv)) return false
  return (await loadWhitelist(io, rt)).includes(binOf(argv))
}

/** S5: repo `executors[].env` without the variables that change which code an allowed binary runs (core executorEnv). */
export function safeExecutorEnv(io: Io, env: Record<string, string> | undefined): Record<string, string> {
  const r = executorEnv(env)
  for (const k of r.dropped) debug(io, `executors env ${k}: ігнорується (змінює, який код запускається)`)
  return r.env
}

// ───────────────────────── containment (H02) ─────────────────────────

const normPath = (p: string, windows: boolean): string => {
  const t = p.replace(/\\/g, '/').replace(/\/+$/, '')
  return windows ? t.toLowerCase() : t
}

async function realRootOf(io: Io, rt: Runtime): Promise<string> {
  if (rt.realRoot?.root === rt.root) return rt.realRoot.real
  const st = await io.fs.stat?.(rt.root, { resolve: true }).catch(() => undefined)
  const real = st?.realPath ?? rt.root
  rt.realRoot = { root: rt.root, real }
  return real
}

function under(real: string, root: string, windows: boolean): boolean {
  const r = normPath(real, windows)
  const base = normPath(root, windows)
  return r === base || r.startsWith(base + '/')
}

/**
 * Does an existing absolute path land inside the repo once symlinks resolve (H02)? A port without `fs.stat` (fake
 * ports) keeps the lexical check only; one whose stat does not resolve refuses a path that is itself a link.
 */
export async function insideRealRoot(io: Io, rt: Runtime, path: string): Promise<boolean> {
  if (!io.fs.stat) return true
  const st = await io.fs.stat(path, { resolve: true }).catch(() => undefined)
  if (!st) return false
  if (st.realPath === undefined) return st.isLink !== true && st.kind !== 'other'
  return under(st.realPath, await realRootOf(io, rt), rt.windows)
}

/**
 * Where a write to `path` would land stays inside the repo (H01): the path itself when it exists (a symlink is
 * refused outright), else its nearest existing ancestor resolved, plus the rest of the path.
 */
export async function writableInsideRoot(io: Io, rt: Runtime, path: string): Promise<boolean> {
  if (!io.fs.stat) return true
  const own = await io.fs.stat(path, { resolve: true }).catch(() => undefined)
  if (own) return own.isLink !== true && (own.realPath === undefined ? own.kind === 'file' : under(own.realPath, await realRootOf(io, rt), rt.windows))
  const parts = path.replace(/\\/g, '/').split('/')
  for (let i = parts.length - 1; i > 0; i--) {
    const dir = parts.slice(0, i).join('/') || '/'
    const st = await io.fs.stat(dir, { resolve: true }).catch(() => undefined)
    if (!st) continue
    if (st.realPath === undefined) return st.isLink !== true
    return under(`${st.realPath.replace(/[\\/]+$/, '')}/${parts.slice(i).join('/')}`, await realRootOf(io, rt), rt.windows)
  }
  return false
}

/** Text of a repo file: repo-relative, no `..`, and its real path inside the real root (no symlink escape, H02). */
export async function readRepoFile(io: Io, rt: Runtime, rel: string): Promise<string | undefined> {
  if (!insideRoot(rel)) return undefined
  const path = join(rt.root, rel)
  if (!(await insideRealRoot(io, rt, path))) {
    debug(io, `${rel}: шлях веде за межі репозиторію (symlink) — не читається`)
    return undefined
  }
  const t = await io.fs.read(path).catch(() => undefined)
  return typeof t === 'string' ? t : undefined
}

// ───────────────────────── $.store cache budget (R2) ─────────────────────────

/** Every `cache:*` entry with its size and write time, so the store (4 MiB for every repo) is bounded. Trust and
 *  `data:` keys are never evicted: only keys listed here (or unlisted `cache:` keys) are deleted. */
export const CACHE_INDEX = 'cache-index'
const CACHE_BUDGET = 1_500_000
const CACHE_ENTRY_MAX = 64_000
interface CacheIndex { v: 1; entries: Record<string, { size: number; at: number }> }
const swept = new WeakSet<Runtime>()

async function readIndex(io: Io): Promise<CacheIndex> {
  const v = (await io.store.get(CACHE_INDEX).catch(() => undefined)) as CacheIndex | undefined
  return v && v.v === 1 && v.entries && typeof v.entries === 'object' ? v : { v: 1, entries: {} }
}

/** Index writes in flight: render runs @run/@call nodes in parallel, and each put reads, changes and writes the one
 *  `cache-index`, so puts are chained (as journal flushes are) or one would drop another's entry from the budget. */
let cacheChain: Promise<void> = Promise.resolve()

/** Store a cache entry within the budget, oldest entries evicted first. */
export function cachePut(io: Io, rt: Runtime, key: string, value: unknown): Promise<void> {
  const run = cacheChain.then(() => cachePutNow(io, rt, key, value))
  cacheChain = run.catch(() => undefined)
  return run
}

async function cachePutNow(io: Io, rt: Runtime, key: string, value: unknown): Promise<void> {
  const size = JSON.stringify(value).length
  if (size > CACHE_ENTRY_MAX) return
  const idx = await readIndex(io)
  if (!swept.has(rt)) {
    swept.add(rt)
    // Entries written before the index (or lost to a concurrent index write) would never be evicted.
    const keys = await io.store.keys?.().catch(() => undefined)
    for (const k of keys ?? []) if (k.startsWith('cache:') && !idx.entries[k]) await io.store.delete(k).catch(() => undefined)
  }
  idx.entries[key] = { size, at: now() }
  let total = Object.values(idx.entries).reduce((n, e) => n + e.size, 0)
  for (const [k] of Object.entries(idx.entries).sort((a, b) => a[1].at - b[1].at)) {
    if (total <= CACHE_BUDGET) break
    if (k === key) continue
    total -= idx.entries[k].size
    delete idx.entries[k]
    await io.store.delete(k).catch(() => undefined)
  }
  try {
    await io.store.set(key, value)
  } catch (err) {
    delete idx.entries[key]
    debug(io, `cache store failed: ${String((err as Error)?.message ?? err)}`)
  }
  await io.store.set(CACHE_INDEX, idx).catch((err: unknown) => debug(io, `cache index store failed: ${String(err)}`))
}

/** Drop every cache entry (a full store refused a trust write): trust outranks any cache. */
export async function clearCacheStore(io: Io): Promise<void> {
  const idx = await readIndex(io)
  const keys = new Set([...Object.keys(idx.entries), ...((await io.store.keys?.().catch(() => undefined)) ?? []).filter((k) => k.startsWith('cache:'))])
  for (const k of keys) await io.store.delete(k).catch(() => undefined)
  await io.store.set(CACHE_INDEX, { v: 1, entries: {} } satisfies CacheIndex).catch(() => undefined)
}

/** gate.json `prompt.dir`, repo-relative; an absolute or `..` value falls back to `.claude/prompt` (M05, as dsl.ts
 *  promptDir, which cannot be imported here: dsl.ts imports this file). */
export function configuredPromptDir(cfg: { prompt?: { dir?: string } }): string {
  const dir = (cfg.prompt?.dir ?? '.claude/prompt').replace(/\\/g, '/').replace(/^\.\//, '').replace(/\/+$/, '')
  return dir && insideRoot(dir) ? dir : '.claude/prompt'
}

/** Largest input passed in CONTEXT_GATE_INPUT (bytes); larger inputs come only on stdin (CLI INPUT_ENV_MAX). */
const INPUT_ENV_MAX = 64 * 1024

/** UTF-8 byte length of a string (no Buffer in the mod runtime). */
function utf8Length(s: string): number {
  if (s.length * 3 <= INPUT_ENV_MAX) return s.length * 3
  let n = 0
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i)
    if (c < 0x80) n += 1
    else if (c < 0x800) n += 2
    else if (c >= 0xd800 && c <= 0xdbff) { n += 4; i++ }
    else n += 3
  }
  return n
}

/** A per-process timeout: the render's remaining budget when it passes one, never more than 10 s. */
function boundedTimeout(timeoutMs: number | undefined): number {
  return timeoutMs !== undefined && timeoutMs > 0 ? Math.min(timeoutMs, 10_000) : 10_000
}

export async function runArgv(io: Io, rt: Runtime, argv: string[], init: { stdin?: string; timeoutMs: number; env?: Record<string, string> }): Promise<{ exitCode: number; stdout: string; stderr: string; ms: number }> {
  const t0 = now()
  try {
    const r = await io.process.run(argv, { cwd: rt.root, timeoutMs: Math.max(100, Math.min(init.timeoutMs, 600_000)), ...(init.stdin !== undefined ? { stdin: init.stdin } : {}), ...(init.env ? { env: init.env } : {}) })
    return { exitCode: r.exitCode, stdout: r.stdout, stderr: r.stderr, ms: now() - t0 }
  } catch (err) {
    return { exitCode: -1, stdout: '', stderr: String((err as Error)?.message ?? err), ms: now() - t0 }
  }
}

function parseOut(stdout: string): Value {
  const t = stdout.trim()
  if (!t) return ''
  try { return JSON.parse(t) as Value } catch { return t }
}

const SKIP_DIRS = new Set(['.git', 'node_modules', 'dist', '.compiled', '.cache', '.next', 'coverage', '__pycache__', '.venv'])

/** Repo files under `base` (repo-relative POSIX, sorted), skipping the CLI's `walkFiles` dirs; bounded. */
export async function walkRepo(io: Io, rt: Runtime, base = '', limits: { dirs?: number; files?: number } = {}): Promise<string[]> {
  if (!insideRoot(base || '.')) return []
  const out: string[] = []
  const maxDirs = limits.dirs ?? 2000
  const maxFiles = limits.files ?? 20_000
  const queue: string[] = [base]
  let visited = 0
  while (queue.length && visited < maxDirs && out.length < maxFiles) {
    const rel = queue.shift()!
    visited++
    const entries = [...(await io.fs.list(rel ? join(rt.root, rel) : rt.root).catch(() => []))].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    for (const e of entries) {
      const p = rel ? `${rel}/${e.name}` : e.name
      if (e.kind === 'dir' && !e.isLink) { if (!SKIP_DIRS.has(e.name)) queue.push(p) }
      else if (e.kind === 'file') out.push(p)
    }
  }
  return out.sort()
}

/** Walk the static prefix of a glob, then core `selectExamples` / `exampleValue` (the CLI's `fs.examples` too). */
async function examples(io: Io, rt: Runtime, glob: string, n: number): Promise<Value> {
  const segs = glob.split('/')
  const prefix: string[] = []
  for (const s of segs) { if (hasGlobChars(s)) break; prefix.push(s) }
  if (prefix.length === segs.length) prefix.pop()
  const base = prefix.join('/')
  if (!insideRoot(base || '.')) return []
  const found: { path: string; size: number }[] = []
  const queue: { rel: string; depth: number }[] = [{ rel: base, depth: 0 }]
  let visited = 0
  while (queue.length && visited < 300) {
    const { rel, depth } = queue.shift()!
    visited++
    const entries = await io.fs.list(rel ? join(rt.root, rel) : rt.root).catch(() => [])
    for (const e of entries) {
      const p = rel ? `${rel}/${e.name}` : e.name
      if (e.kind === 'dir' && !e.isLink && depth < 8 && !e.name.startsWith('.') && e.name !== 'node_modules') queue.push({ rel: p, depth: depth + 1 })
      else if (e.kind === 'file') found.push({ path: p, size: e.size })
    }
  }
  const out: Value[] = []
  for (const f of selectExamples(found, glob, Math.min(n, 20))) {
    const body = await readRepoFile(io, rt, f.path)
    out.push(exampleValue(f, body ?? ''))
  }
  return out
}

/** `fs.glob(pattern)`: repo files matching a glob (a slash-less pattern matches the basename), as the CLI. */
async function globFiles(io: Io, rt: Runtime, pattern: string): Promise<Value> {
  if (!pattern) return []
  const segs = pattern.split('/')
  const prefix: string[] = []
  for (const s of segs) { if (hasGlobChars(s)) break; prefix.push(s) }
  if (prefix.length === segs.length) prefix.pop()
  const m = compileGlob(pattern, { matchBase: true })
  const base = pattern.includes('/') && !pattern.startsWith('!') ? prefix.join('/') : ''
  return (await walkRepo(io, rt, base)).filter((f) => m(f))
}

/** CLI `fill`: `{0}` positional, `{name}` kwargs, `{x}` the next positional. */
function fillPlaceholders(argv: readonly string[], args: Value[], kwargs: Record<string, Value>): string[] {
  let i = 0
  const str = (v: Value | undefined): string => (v === undefined || v === null ? '' : typeof v === 'string' ? v : JSON.stringify(v))
  return argv.map((a) => a.replace(/\{(\w+)\}/g, (_m, k: string) => {
    if (/^\d+$/.test(k)) return str(args[Number(k)])
    if (k in kwargs) return str(kwargs[k])
    return str(args[i++])
  }))
}

/** gate.json providers plus `<prompt dir>/lib/*.{ts,mts,js,mjs}` as `module` providers named by file (as the CLI). */
export async function providerConfigs(io: Io, rt: Runtime, promptDir: string): Promise<Record<string, ProviderConfig>> {
  const out: Record<string, ProviderConfig> = { ...(rt.cfg.providers ?? {}) }
  const lib = `${promptDir}/lib`
  const entries = await io.fs.list(join(rt.root, lib)).catch(() => [])
  for (const e of [...entries].sort((a, b) => a.name.localeCompare(b.name))) {
    const m = e.kind === 'file' ? /^([\w-]+)\.(ts|mts|js|mjs)$/.exec(e.name) : null
    if (m && !out[m[1]]) out[m[1]] = { kind: 'module', path: `${lib}/${e.name}` }
  }
  return out
}

export interface HostDeps {
  trusted: boolean
  repoKey: string
  /** Section text by id for `prompt://` lazy refs. */
  itemBody: RenderHostExt['itemBody']
  /** Parsed `.mdc` rules for `cursor.match(path)`. */
  rules: () => Promise<MdcRule[]>
  /** Prompt dir (`.claude/prompt`): `scripts/` for `scripts.*`. */
  promptDir?: string
  /** Providers from `providerConfigs` (default: gate.json providers only). */
  providers?: Record<string, ProviderConfig>
}

/** The mod's RenderHost, plus the shim helpers the layers use for module tools and G158. */
export interface ModHost extends RenderHostExt {
  /** One shim batch into a repo module; per-call errors in `errors[i]`. */
  shim(path: string, calls: ShimCall[], timeoutMs?: number): Promise<ShimResponse>
  /** Exported function names of a module (G158), asked once per session; undefined when the shim can't tell. */
  listExports(path: string): Promise<string[] | undefined>
  /** Effective providers (config + lib modules). */
  providerConfigs: Record<string, ProviderConfig>
}

export function makeRenderHost(io: Io, rt: Runtime, deps: HostDeps): ModHost {
  const cfg = rt.cfg
  const executors = executorsOf(cfg)
  const providers = deps.providers ?? cfg.providers ?? {}
  const promptDir = deps.promptDir ?? configuredPromptDir(cfg)
  const callables = ['git.log', 'fs.examples', 'fs.glob', 'fs.exists', 'cursor.match', 'scripts.*']
  for (const [name, p] of Object.entries(providers)) if (!p.builtin && !BUILTIN_PROVIDERS.has(name)) callables.push(`${name}.*`)

  const cached = async (key: string, ttl: string | undefined, compute: () => Promise<Value | undefined>): Promise<Value | undefined> => {
    const ttlMs = parseDuration(ttl)
    if (ttlMs !== undefined) {
      const e = await host.cacheGet!(key)
      if (e && now() - e.at <= ttlMs) return e.value
    }
    const v = await compute()
    if (v !== undefined && ttlMs !== undefined) await host.cacheSet!(key, v)
    return v
  }

  const moduleCall = async (name: string, p: ProviderConfig, fn: string, args: Value[], kwargs: Record<string, Value>): Promise<Value> => {
    if (!deps.trusted || !p.path) return null
    const key = `prov:${name}:${fn}:${hash(JSON.stringify([args, kwargs]))}`
    const v = await cached(key, p.cache, async () => {
      const r = await host.shim(p.path!, [{ fn, args, kwargs }])
      if (r.errors[0]) { debug(io, `provider ${name}.${fn}: ${r.errors[0]}`); return undefined }
      return r.results[0] ?? null
    })
    return v === undefined ? null : v
  }

  /** `scripts.<fn>(…)`: run `<prompt dir>/scripts/<fn>.*` with `{ ctx, args }` on stdin (CLI `Providers.script`). */
  const script = async (fn: string, args: Value[], kwargs: Record<string, Value>, timeoutMs = 10_000): Promise<Value> => {
    const dir = `${promptDir}/scripts`
    const file = (await walkRepo(io, rt, dir, { dirs: 50, files: 500 })).find((f) => scriptFnName(f) === fn)
    if (!file) { debug(io, `scripts.${fn}: скрипт не знайдено в ${dir}`); return null }
    if (!deps.trusted) return null
    if (!(await insideRealRoot(io, rt, join(rt.root, file)))) { debug(io, `scripts.${fn}: ${file} веде за межі репозиторію`); return null }
    const text = (await readRepoFile(io, rt, file)) ?? ''
    const argv = scriptArgv(join(rt.root, file), scriptLang(file, text))
    if (!(await allowedBinary(io, rt, argv))) { debug(io, `scripts.${fn}: ${argv[0]} поза білим списком`); return null }
    const key = `scripts:${fn}:${hash(text)}:${hash(JSON.stringify([args, kwargs]))}`
    const v = await cached(key, cfg.prompt?.runCacheDefault ?? '5m', async () => {
      const r = await runArgv(io, rt, argv, { stdin: scriptStdin(args, kwargs), timeoutMs })
      if (r.exitCode !== 0) { debug(io, `scripts.${fn}: exit ${r.exitCode}: ${r.stderr.trim().split('\n')[0] ?? ''}`); return undefined }
      const out = r.stdout.trim()
      if (!out) return null
      try { return JSON.parse(out) as Value } catch { return out }
    })
    return v ?? null
  }

  const host: ModHost = {
    trusted: deps.trusted,
    now: () => now(),
    callables,
    providerConfigs: providers,
    readFile: (path) => readRepoFile(io, rt, path),
    async run(req) {
      const ex = executorFor(executors, req.lang)
      if (!ex) return { exitCode: -1, stdout: '', stderr: `виконавця «${req.lang}» не оголошено в executors`, ms: 0 }
      const inv = executorInvocation(ex, req.code, req.stdin)
      if (!deps.trusted || !(await allowedBinary(io, rt, inv.argv))) return { exitCode: -1, stdout: '', stderr: 'виконання заборонено (довіра / білий список / allowScripts)', ms: 0 }
      const timeoutMs = Math.min(req.timeoutMs, parseDuration(ex.timeout) ?? req.timeoutMs)
      // CONTEXT_GATE_INPUT only for small inputs: a large scope in the environment fails exec with E2BIG (M46/P3);
      // stdin always carries the input.
      const input: Record<string, string> = utf8Length(req.stdin) <= INPUT_ENV_MAX ? { CONTEXT_GATE_INPUT: req.stdin } : {}
      return runArgv(io, rt, inv.argv, { stdin: inv.stdin, timeoutMs, env: { ...safeExecutorEnv(io, ex.env), ...input, CONTEXT_GATE_ROOT: rt.root } })
    },
    async shim(path, calls, timeoutMs = 10_000) {
      const fail = (msg: string): ShimResponse => ({ results: calls.map(() => null), errors: calls.map(() => msg) })
      if (!deps.trusted) return fail('репозиторій не довірений')
      if (!insideRoot(path)) return fail(`модуль ${path} поза репозиторієм`)
      const file = join(rt.root, path)
      if (!(await io.fs.exists(file).catch(() => false))) return fail(`модуль ${path} не знайдено`)
      if (!(await insideRealRoot(io, rt, file))) return fail(`модуль ${path} веде за межі репозиторію`)
      const cmd = shimCommand(path, file, calls, executors)
      if (!cmd.ok) return fail(cmd.error)
      if (!(await allowedBinary(io, rt, cmd.argv))) return fail(`${cmd.argv[0]} не в білому списку або allowScripts вимкнено`)
      const r = await runArgv(io, rt, cmd.argv, { stdin: cmd.stdin, timeoutMs })
      return parseShimOutput(cmd, r, calls)
    },
    async call(req) {
      if (!deps.trusted || !insideRoot(req.path)) throw new Error('виклик заборонено')
      // The render passes what is left of its budget: the shim never outlives the render deadline (M62).
      const r = await host.shim(req.path, req.calls, boundedTimeout(req.timeoutMs))
      const err = r.errors.find((e) => e)
      if (err) throw new Error(err)
      return r.results
    },
    async listExports(path) {
      if (rt.moduleExports.has(path)) return rt.moduleExports.get(path) ?? undefined
      const r = await host.shim(path, [{ fn: '__exports__', args: [] }])
      const v = r.results[0]
      const names = !r.errors[0] && Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : null
      rt.moduleExports.set(path, names)
      return names ?? undefined
    },
    async mcp(req) {
      if (!deps.trusted) throw new Error('репозиторій не довірений')
      const r = await io.mcp.call(req.server, req.tool, req.args)
      if (r.isError) throw new Error(`MCP ${req.server}.${req.tool} повернув помилку`)
      if (r.structuredContent !== undefined) return r.structuredContent as Value
      const text = r.content.map((b) => ('text' in b && typeof b.text === 'string' ? b.text : '')).join('\n')
      return parseOut(text)
    },
    async cacheGet(key) {
      const v = (await io.store.get(`cache:${deps.repoKey}:${key}`).catch(() => undefined)) as { value: Value; at: number } | undefined
      return v && typeof v.at === 'number' ? v : undefined
    },
    async cacheSet(key, value) {
      await cachePut(io, rt, `cache:${deps.repoKey}:${key}`, { value, at: now() })
    },
    registerLazy(name, description, ref) {
      const full = `${OWN_TOOL_PREFIX}${name}`
      const known = rt.tools.get(full)
      if (known && known.kind === 'lazy' && known.ref === ref) return
      rt.tools.set(full, { kind: 'lazy', ref, description })
      void io.tool.register({ name, description: `${description} (context-gate: повертає текст включення)`, inputSchema: { type: 'object', properties: {}, additionalProperties: false } })
        .catch((err: unknown) => debug(io, `lazy tool ${name}: ${String(err)}`))
    },
    itemBody: deps.itemBody,
    async provider(req: ProviderCallRequest) {
      const { ns, fn, args, kwargs } = req
      if (req.path === 'fs.examples') return examples(io, rt, String(args[0] ?? '**/*'), typeof args[1] === 'number' ? args[1] : 1)
      if (req.path === 'fs.glob') return globFiles(io, rt, String(args[0] ?? ''))
      if (req.path === 'fs.exists') {
        const p = String(args[0] ?? '')
        return !!p && insideRoot(p) && (await io.fs.exists(join(rt.root, p)).catch(() => false))
      }
      if (req.path === 'cursor.match') return cursorMatch(await deps.rules(), String(args[0] ?? ''), { nocase: rt.windows })
      if (req.path === 'git.log') {
        const n = Math.max(1, Math.min(50, Number(args[0] ?? 5)))
        const r = await runArgv(io, rt, ['git', 'log', '--oneline', `-${n}`], { timeoutMs: 5000 })
        return r.exitCode === 0 ? r.stdout.trim().split('\n').filter(Boolean) : []
      }
      if (ns === 'scripts') return script(fn, args, kwargs, boundedTimeout(req.timeoutMs))
      const p = providers[ns]
      if (!p || p.builtin) return null
      if (p.kind === 'cli') {
        const fns = p.functions
        const tpl = fns && !Array.isArray(fns) ? fns[fn] : undefined
        const argv = tpl ? fillPlaceholders(tpl, args, kwargs) : Array.isArray(fns) && fns.includes(fn) && p.command ? [...p.command, fn, ...args.map((a) => (typeof a === 'string' ? a : JSON.stringify(a)))] : undefined
        if (!argv || !deps.trusted || !(await allowedBinary(io, rt, argv))) return null
        const r = await runArgv(io, rt, argv, { timeoutMs: boundedTimeout(req.timeoutMs) })
        const res = providerResultOk(p, r.exitCode, r.stdout) // okExitCodes / parseOnError (eslint -f json exits 1)
        if (!res.ok) throw new Error(`${req.path}: ${res.error}`)
        return res.value
      }
      if (p.kind === 'module') return moduleCall(ns, p, fn, args, kwargs)
      return null
    },
  }
  return host
}

/** Data of providers (file / cli / module / mcp) for the render scope, cached per their `cache`.
 * `host.providerConfigs` (a `ModHost`) adds the `lib/` modules; `only` reads one provider (gates.ts). */
export async function providerData(io: Io, rt: Runtime, host: RenderHostExt & { providerConfigs?: Record<string, ProviderConfig> }, only?: string): Promise<Record<string, Value>> {
  const out: Record<string, Value> = {}
  for (const [name, p] of Object.entries(host.providerConfigs ?? rt.cfg.providers ?? {})) {
    if (only !== undefined && name !== only) continue // gates[].provider reads one provider (gates.ts)
    if (p.builtin || BUILTIN_PROVIDERS.has(name)) continue
    try {
      const cacheMs = parseDuration(p.cache)
      const key = `provider:${name}`
      if (cacheMs !== undefined) {
        const c = await host.cacheGet?.(key)
        if (c && now() - c.at <= cacheMs) { out[name] = c.value; continue }
      }
      let v: Value = null
      if (p.kind === 'file' && p.path) {
        const t = await host.readFile(p.path)
        if (t === undefined) throw new Error(`немає файлу ${p.path}`)
        const f = fileProviderValue(p.path, t, p.pick) // core: .json parsed + dotted `pick`, else the text
        if ('error' in f) throw new Error(f.error)
        v = 'value' in f ? f.value : markdownProviderValue(t) // Markdown: { meta, body, headings }, as in the CLI
      } else if (p.kind === 'cli' && p.command?.length) {
        if (!host.trusted || !(await allowedBinary(io, rt, p.command))) throw new Error('не довірено')
        const r = await runArgv(io, rt, p.command, { timeoutMs: 10_000 })
        const res = providerResultOk(p, r.exitCode, r.stdout)
        if (!res.ok) throw new Error(res.error)
        v = pickFields(res.value, p.pick)
      } else if (p.kind === 'module' && p.path) {
        // Repo module (`<prompt dir>/lib/*.ts`, gate.json `module`): its default export through the node shim.
        const shim = (host as Partial<ModHost>).shim
        if (!host.trusted || !shim) throw new Error('не довірено')
        const r = await shim(p.path, [{ fn: '__default__', args: [] }])
        if (r.errors[0]) throw new Error(r.errors[0])
        v = pickFields(r.results[0] ?? null, p.pick)
      } else if (p.kind === 'mcp' && p.tool && host.mcp) {
        const m = /^mcp__(.+?)__(.+)$/.exec(p.tool)
        if (!m) throw new Error(`tool ${p.tool}`)
        v = await host.mcp({ server: m[1], tool: m[2], args: (p.args ?? {}) as Record<string, Value> })
      } else continue
      out[name] = v
      if (cacheMs !== undefined) await host.cacheSet?.(key, v)
    } catch (err) {
      debug(io, `provider ${name}: ${String((err as Error)?.message ?? err)}`)
      if (p.onError === 'fail' || p.onError === 'skip') continue
      out[name] = { unverified: true }
    }
  }
  return out
}

